// ============================================================================
// SDMMC_ADMA_apb: APB4 register wrapper around SDMMC_ADMA_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SDMMC_ADMA.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SDMMC_ADMA.md
// ============================================================================
module SDMMC_ADMA_apb #(
  parameter logic [3:0] AXI_ID = 4'd11
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sd_clk,
  inout tri cmd,
  inout tri [7:0] dat,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C610100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [18:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd19) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [9:0]    c_clk_div;
  logic          c_clk_en;
  logic [1:0]    c_bus_w;
  logic [11:0]   c_blksz;
  logic [15:0]   c_blkcnt;
  logic [23:0]   c_dto;
  logic [31:0]   c_adma_addr;
  logic [5:0]    c_c_idx;
  logic [31:0]   c_c_arg;
  logic [1:0]    c_c_rsp;
  logic          c_c_crc_chk;
  logic          c_c_idx_chk;
  logic [1:0]    c_c_data;
  logic          c_c_start;
  logic          c_dat_reset;
  logic [31:0]   c_rsp0;
  logic [31:0]   c_rsp1;
  logic [31:0]   c_rsp2;
  logic [31:0]   c_rsp3;
  logic          c_cmd_busy;
  logic          c_dat_busy;
  logic [4:0]    c_c_err;
  logic [7:0]    c_d_err;
  logic [15:0]   c_blk_done;
  logic [31:0]   c_adma_cur;
  logic          c_cmd_done;
  logic          c_cmd_err;
  logic          c_xfer_done;
  logic          c_xfer_err;
  logic          c_dma_int;
  SDMMC_ADMA_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sd_clk(sd_clk),
    .cmd(cmd),
    .dat(dat),
    .clk_div(c_clk_div),
    .clk_en(c_clk_en),
    .bus_w(c_bus_w),
    .blksz(c_blksz),
    .blkcnt(c_blkcnt),
    .dto(c_dto),
    .adma_addr(c_adma_addr),
    .c_idx(c_c_idx),
    .c_arg(c_c_arg),
    .c_rsp(c_c_rsp),
    .c_crc_chk(c_c_crc_chk),
    .c_idx_chk(c_c_idx_chk),
    .c_data(c_c_data),
    .c_start(c_c_start),
    .dat_reset(c_dat_reset),
    .rsp0(c_rsp0),
    .rsp1(c_rsp1),
    .rsp2(c_rsp2),
    .rsp3(c_rsp3),
    .cmd_busy(c_cmd_busy),
    .dat_busy(c_dat_busy),
    .c_err(c_c_err),
    .d_err(c_d_err),
    .blk_done(c_blk_done),
    .adma_cur(c_adma_cur),
    .cmd_done(c_cmd_done),
    .cmd_err(c_cmd_err),
    .xfer_done(c_xfer_done),
    .xfer_err(c_xfer_err),
    .dma_int(c_dma_int),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [12:0] r_CFG;   // 12'h014 CFG
  logic [27:0] r_BLK;   // 12'h018 BLK
  logic [23:0] r_DTO;   // 12'h01C DTO
  logic [31:0] r_ADMA_ADDR;   // 12'h020 ADMA_ADDR
  logic [31:0] r_CMD_ARG;   // 12'h024 CMD_ARG
  logic [11:0] r_CMD_CTRL;   // 12'h028 CMD_CTRL
  logic [1:0] p_CMD;   // 12'h02C CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 13'hF9;
      r_BLK <= 28'h1200;
      r_DTO <= 24'hFFFFFF;
      r_ADMA_ADDR <= 32'h0;
      r_CMD_ARG <= 32'h0;
      r_CMD_CTRL <= 12'h300;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[6]) r_BLK <= (r_BLK & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      if (wr && hit[7]) r_DTO <= (r_DTO & ~wmask[23:0]) | (PWDATA[23:0] & wmask[23:0]);
      if (wr && hit[8]) r_ADMA_ADDR <= (r_ADMA_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_CMD_ARG <= (r_CMD_ARG & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_CMD_CTRL <= (r_CMD_CTRL & ~wmask[11:0]) | (PWDATA[11:0] & wmask[11:0]);
      p_CMD <= (wr && hit[11]) ? PWDATA[1:0] & wmask[1:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_clk_div = r_CFG[9:0];
  assign c_clk_en = r_CFG[10:10];
  assign c_bus_w = r_CFG[12:11];
  assign c_blksz = r_BLK[11:0];
  assign c_blkcnt = r_BLK[27:12];
  assign c_dto = r_DTO[23:0];
  assign c_adma_addr = r_ADMA_ADDR[31:0];
  assign c_c_arg = r_CMD_ARG[31:0];
  assign c_c_idx = r_CMD_CTRL[5:0];
  assign c_c_rsp = r_CMD_CTRL[7:6];
  assign c_c_crc_chk = r_CMD_CTRL[8:8];
  assign c_c_idx_chk = r_CMD_CTRL[9:9];
  assign c_c_data = r_CMD_CTRL[11:10];
  assign c_c_start = p_CMD[0:0];
  assign c_dat_reset = p_CMD[1:1];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_cmd_done;
    irq_set[1] = c_cmd_err;
    irq_set[2] = c_xfer_done;
    irq_set[3] = c_xfer_err;
    irq_set[4] = c_dma_int;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_BLK);
      10'd7: apb_rdata = 32'(r_DTO);
      10'd8: apb_rdata = 32'(r_ADMA_ADDR);
      10'd9: apb_rdata = 32'(r_CMD_ARG);
      10'd10: apb_rdata = 32'(r_CMD_CTRL);
      10'd12: apb_rdata = 32'({c_rsp0});
      10'd13: apb_rdata = 32'({c_rsp1});
      10'd14: apb_rdata = 32'({c_rsp2});
      10'd15: apb_rdata = 32'({c_rsp3});
      10'd16: apb_rdata = 32'({c_d_err, c_c_err, c_dat_busy, c_cmd_busy});
      10'd17: apb_rdata = 32'({c_blk_done});
      10'd18: apb_rdata = 32'({c_adma_cur});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
